Going Beyond - Twin Cities Map with leaflet

Below we show how to make the MN counties map in the leaflet package.

Codelibrary(leaflet)

mn_counties_leaf &lt;- mn_counties |&gt; st_transform(4326) 
mn_cities_leaf &lt;- mn_cities |&gt; st_transform(4326)

cities_per_county &lt;- st_join(mn_cities_leaf, mn_counties_leaf) |&gt;
    st_drop_geometry() |&gt; 
    count(name.y) |&gt;                  
    rename(name = name.y)

mn_counties_leaf |&gt; 
    filter(name %in% c("Anoka", "Hennepin", "Ramsey", "Dakota", "Carver", "Washington", "Scott")) |&gt;
    left_join(cities_per_county, by = "name") |&gt;  # explicitly join by the 'name' column
    leaflet() |&gt; 
    addProviderTiles("OpenStreetMap.Mapnik") |&gt; 
    addPolygons(
        color = "#444444", 
        weight = 1, 
        smoothFactor = 0.5, 
        opacity = 1.0,
        fillOpacity = 0.5, 
        fillColor = "yellow",
        highlightOptions = highlightOptions(color = "white", weight = 2, bringToFront = TRUE)
    ) |&gt;
    addCircles(
        data = mn_cities_leaf |&gt; filter(county %in% paste(c("Anoka", "Hennepin", "Ramsey", "Dakota", "Carver", "Washington", "Scott"), "County")), 
        color = "#444444")
